export async function callTool(name, args) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { text, mode, trim } = args;

  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }

  if (!['uppercase', 'lowercase', 'slug'].includes(mode)) {
    throw new Error(`Invalid mode: ${mode}`);
  }

  if (trim !== undefined && typeof trim !== 'boolean') {
    throw new Error('trim must be a boolean');
  }

  const shouldTrim = trim !== undefined ? trim : true;
  let resultText = shouldTrim ? text.trim() : text;

  switch (mode) {
    case 'uppercase':
      resultText = resultText.toUpperCase();
      break;
    case 'lowercase':
      resultText = resultText.toLowerCase();
      break;
    case 'slug':
      resultText = resultText.toLowerCase();
      // Replace runs of non-alphanumeric characters with one hyphen
      resultText = resultText.replace(/[^a-z0-9]+/g, '-');
      // Remove leading and trailing hyphens
      resultText = resultText.replace(/^-+|-+$/g, '');
      break;
  }

  return {
    content: [{ type: 'text', text: resultText }]
  };
}
